"""Exact, immutable local datasheet evidence capture and replay."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path, PurePosixPath

from pyocd_debug_mcp.firmstore.store import FirmStore, ImmutableArtifactError

PARSER_VERSION = "pdf-exact-v2"


class DatasheetEvidenceError(ValueError):
    """The local PDF cannot serve as deterministic setup evidence."""


@dataclass(frozen=True, slots=True)
class DatasheetEvidence:
    sha256: str
    reference: str
    parser_version: str = PARSER_VERSION

    def source_document(self) -> dict[str, str]:
        return {
            "sha256": self.sha256,
            "reference": self.reference,
            "parser_version": self.parser_version,
        }


def read_datasheet_pdf(path: Path) -> bytes:
    """Read exact bytes from a non-empty local PDF without an arbitrary size policy."""

    try:
        size = path.stat().st_size
        if size < 5 or not path.is_file():
            raise DatasheetEvidenceError("datasheet evidence must be a non-empty PDF file")
        payload = path.read_bytes()
    except OSError as exc:
        raise DatasheetEvidenceError(f"datasheet PDF could not be read: {exc}") from exc
    if len(payload) != size:
        raise DatasheetEvidenceError("datasheet PDF changed while it was being read")
    if not payload.startswith(b"%PDF-"):
        raise DatasheetEvidenceError("datasheet evidence must be a PDF file")
    return payload


def capture_datasheet_evidence(store: FirmStore, source: Path) -> DatasheetEvidence:
    """Copy exact PDF bytes into immutable project evidence after server hashing."""

    payload = read_datasheet_pdf(source.expanduser().resolve())
    digest = hashlib.sha256(payload).hexdigest()
    destination = store.layout.datasheet_evidence(digest)
    if not destination.is_file():
        try:
            store.atomic_create_bytes(destination, payload)
        except ImmutableArtifactError:
            # Another server instance may have won the content-addressed
            # create. The bytes still have to replay exactly.
            pass
    try:
        if destination.read_bytes() != payload:
            raise DatasheetEvidenceError("datasheet evidence digest collision")
    except OSError as exc:
        raise DatasheetEvidenceError(f"captured datasheet evidence could not be read: {exc}") from exc
    reference = PurePosixPath(destination.relative_to(store.layout.project_root).as_posix()).as_posix()
    return DatasheetEvidence(digest, reference)


def replay_datasheet_evidence(
    store: FirmStore, reference: str, expected_sha256: str
) -> DatasheetEvidence:
    """Re-hash a captured PDF and reject path escape, loss, or mutation."""

    relative = PurePosixPath(reference)
    if relative.is_absolute() or ".." in relative.parts:
        raise DatasheetEvidenceError("datasheet evidence reference must be project-relative")
    path = (store.layout.project_root / Path(*relative.parts)).resolve()
    root = store.layout.project_root.resolve()
    if not path.is_relative_to(root):
        raise DatasheetEvidenceError("datasheet evidence reference escapes the project")
    payload = read_datasheet_pdf(path)
    actual = hashlib.sha256(payload).hexdigest()
    if actual != expected_sha256:
        raise DatasheetEvidenceError("captured datasheet evidence changed")
    if path != store.layout.datasheet_evidence(actual).resolve():
        raise DatasheetEvidenceError("datasheet evidence reference is not canonical")
    return DatasheetEvidence(actual, reference)

def derive_candidate_binding(pack_path: Path, part_number: str) -> DeviceBinding:
    """Derive one exact/wildcard PDSC leaf and canonical target from quarantined bytes."""

    payload = read_pack_bytes(pack_path)
    return _derive_verified_binding(
        VerifiedPack(
            pack_path,
            PackSpec("candidate", "", pack_path.name, "", "0" * 64),
            payload,
        ),
        part_number,
    )


@dataclass(frozen=True, slots=True)
class DeviceSupportCandidate:
    """One verified exact part-to-pack-to-target candidate issued by the server."""

    candidate_id: str
    part_number: str
    pdsc_device: str
    pyocd_target: str
    pack_id: str
    pack_filename: str
    pack_sha256: str
    identity_proof: LiveIdentityProof | None = None

    @classmethod
    def from_verified_pack(
        cls, selected: VerifiedPack, binding: DeviceBinding
    ) -> "DeviceSupportCandidate":
        material = "\0".join(
            (
                selected.spec.sha256,
                binding.part_number.casefold(),
                binding.pdsc_device.casefold(),
                binding.pyocd_target.casefold(),
                str(binding.identity_proof.to_document() if binding.identity_proof else None),
            )
        ).encode("utf-8")
        return cls(
            hashlib.sha256(material).hexdigest(),
            binding.part_number,
            binding.pdsc_device,
            binding.pyocd_target,
            selected.spec.id,
            selected.spec.filename,
            selected.spec.sha256,
            binding.identity_proof,
        )

    @property
    def support_id(self) -> str:
        """Return the immutable identifier persisted by generic profiles.

        Candidate IDs are already domain-separated from their component tuple
        and are deterministic for the exact registered authority.  Naming the
        persisted value separately avoids callers mistaking a target string for
        authority.
        """

        return self.candidate_id

    def to_authority_document(self) -> dict[str, str]:
        """Return the closed server-generated source record for a profile/map."""

        return {
            "kind": "resolved_pack",
            "support_id": self.support_id,
            "pack_id": self.pack_id,
            "pack_filename": self.pack_filename,
            "pack_sha256": self.pack_sha256,
            "pdsc_device": self.pdsc_device,
            "pyocd_target": self.pyocd_target,
        }


@dataclass(frozen=True, slots=True)
class BuiltInTargetSupportCandidate:
    """Agent-resolved built-in pyOCD target, replayable from the installed registry.

    The target name is a research result, not authority by itself. Authority is
    established by resolving that exact installed target, hashing its static
    memory geometry, and recording a compatible live Arm CPUID proof.
    """

    part_number: str
    pyocd_target: str
    geometry_sha256: str
    identity_proof: LiveIdentityProof | None = None

    @property
    def support_id(self) -> str:
        proof = self.identity_proof.to_document() if self.identity_proof is not None else None
        material = {
            "kind": "resolved_builtin_target",
            "part_number": normalize_part_number(self.part_number),
            "pyocd_target": self.pyocd_target.casefold(),
            "geometry_sha256": self.geometry_sha256,
            "identity_proof": proof,
        }
        return hashlib.sha256(
            json.dumps(material, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()

    def with_identity_proof(self, observed_cpuid: int) -> "BuiltInTargetSupportCandidate":
        proof = live_cpuid_compatibility_proof(observed_cpuid)
        return BuiltInTargetSupportCandidate(
            self.part_number,
            self.pyocd_target,
            self.geometry_sha256,
            proof,
        )

    def to_authority_document(self) -> dict[str, str]:
        if self.identity_proof is None:
            raise PackProvisionError(
                "built-in target support has not captured a live compatible identity proof"
            )
        proof = self.identity_proof
        return {
            "kind": "resolved_builtin_target",
            "support_id": self.support_id,
            "part_number": self.part_number,
            "pyocd_target": self.pyocd_target,
            "geometry_sha256": self.geometry_sha256,
            "identity_address": str(proof.address),
            "identity_expected": str(proof.expected),
            "identity_mask": str(proof.mask),
            "identity_width_bits": str(proof.width_bits),
    if candidate.casefold().startswith("probe:"):
        candidate = candidate.split(":", 1)[1]
    return _stable_identity_equal(candidate, probe.probe_id) or _stable_identity_equal(
        candidate, probe.usb_serial
    )


_setup_research = ResearchTracker()
_setup_target_overrides: dict[str, str] = {}
_setup_attachment_overrides: dict[str, tuple[str | None, str, int | None]] = {}
_setup_builtin_candidates: dict[str, BuiltInTargetSupportCandidate] = {}
_setup_selections_by_board: dict[str, PreflightSelections] = {}
_setup_pack_pipelines: dict[
